<?php namespace App\Http\Controllers; use App\Http\Requests\UpdateAdminBookingRequest; use App\Models\{Booking,MeetingRoom}; use App\Services\BookingService; use Illuminate\Http\Request;
class AdminBookingController extends Controller { public function index(Request $r){$bookings=Booking::with(['room','user'])->when($r->status,fn($q,$v)=>$q->where('status',$v))->latest()->paginate(15)->withQueryString();return view('admin.bookings',compact('bookings'));} public function edit(Booking $booking){$booking->load(['user','room.facilities','approver','histories.actor']);$rooms=MeetingRoom::where('is_active',true)->orderBy('name')->get(['id','name','code','location','capacity']);return view('admin.booking-edit',compact('booking','rooms'));} public function update(UpdateAdminBookingRequest $request,Booking $booking,BookingService $service){$service->updateByAdmin($booking,$request->validated(),$request->user());return redirect()->route('admin.bookings.index')->with('success','Data booking '.$booking->booking_code.' berhasil diperbarui.');} }
